//! The pinned FFmpeg builds (`ffmpeg-runtimes.json`, regenerated by `scripts/update-ffmpeg-runtimes.py`): one release
//! of BtbN's FFmpeg-Builds, its LGPL shared build per platform with the size and SHA-256 of the archive. Nothing that
//! is not listed here is ever downloaded (ADR 0033 §1).

use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;

const EMBEDDED: &str = include_str!("ffmpeg-runtimes.json");
/// Where every pinned asset comes from.
const URL_PREFIX: &str = "https://github.com/BtbN/FFmpeg-Builds/releases/download/";

/// The archive of one platform.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct FfmpegAsset {
    pub name: String,
    pub url: String,
    pub size: u64,
    pub sha256: String,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct FfmpegCatalog {
    pub version: u32,
    pub source: String,
    /// The release tag (also the folder name on disk).
    pub tag: String,
    /// FFmpeg's version of the builds.
    pub release: String,
    pub license: String,
    /// `windows-x64`, `linux-arm64`, ...; macOS has none yet (ADR 0033 §1).
    pub platforms: BTreeMap<String, FfmpegAsset>,
}

/// A folder name: lowercase letters, digits, `.` and `-`, at most 64 characters, not starting with `.`.
pub fn is_tag(t: &str) -> bool {
    !t.is_empty()
        && t.len() <= 64
        && !t.starts_with('.')
        && t.chars()
            .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '.' || c == '-')
}

/// A plain archive name.
pub fn is_archive_name(n: &str) -> bool {
    !n.is_empty()
        && n.len() <= 200
        && !n.starts_with('.')
        && !n.contains("..")
        && (n.ends_with(".zip") || n.ends_with(".tar.xz"))
        && n.chars().all(|c| c.is_ascii_alphanumeric() || matches!(c, '.' | '-' | '_'))
}

fn valid(tag: &str, a: &FfmpegAsset) -> bool {
    let hex = a.sha256.len() == 64 && a.sha256.chars().all(|c| c.is_ascii_hexdigit() && !c.is_ascii_uppercase());
    is_archive_name(&a.name) && hex && a.size > 0 && a.url == format!("{URL_PREFIX}{tag}/{}", a.name) && a.name.contains("lgpl")
}

/// This platform's catalog key.
pub fn current_platform() -> String {
    debrief_ai::runtimes::catalog::platform_key(std::env::consts::OS, std::env::consts::ARCH)
}

impl FfmpegCatalog {
    /// The catalog built into Debrief (validated by the tests, so a parse failure is a build defect).
    pub fn embedded() -> FfmpegCatalog {
        FfmpegCatalog::parse(EMBEDDED).unwrap_or(FfmpegCatalog {
            version: 1,
            source: String::new(),
            tag: String::new(),
            release: String::new(),
            license: String::new(),
            platforms: BTreeMap::new(),
        })
    }

    /// Parses and validates a catalog; invalid assets (not LGPL, not from the pinned release, bad checksums) are
    /// dropped.
    pub fn parse(json: &str) -> Result<FfmpegCatalog, String> {
        let mut c: FfmpegCatalog = serde_json::from_str(json).map_err(|e| format!("the FFmpeg catalog is not valid: {e}"))?;
        if c.version != 1 {
            return Err(format!("unsupported FFmpeg catalog version {}", c.version));
        }
        if !is_tag(&c.tag) {
            return Err("the FFmpeg catalog's release tag is not valid".into());
        }
        let tag = c.tag.clone();
        c.platforms.retain(|_, a| valid(&tag, a));
        Ok(c)
    }

    /// The archive of `platform`, when one is pinned.
    pub fn asset(&self, platform: &str) -> Option<&FfmpegAsset> {
        self.platforms.get(platform)
    }

    /// The same assets as the inference runtime's catalog, so its GitHub source downloads them
    /// (`debrief_ai::runtimes::GithubReleases`: only listed assets, only from GitHub, resumable).
    pub fn as_runtime_catalog(&self) -> debrief_ai::runtimes::RuntimeCatalog {
        debrief_ai::runtimes::RuntimeCatalog {
            version: 1,
            release: self.release.clone(),
            tag: self.tag.clone(),
            commit: String::new(),
            published: String::new(),
            source: self.source.clone(),
            platforms: self
                .platforms
                .iter()
                .map(|(p, a)| {
                    (
                        p.clone(),
                        vec![debrief_ai::runtimes::RuntimeBuild {
                            id: "lgpl".into(),
                            assets: vec![debrief_ai::runtimes::RuntimeAsset {
                                name: a.name.clone(),
                                url: a.url.clone(),
                                size: a.size,
                                sha256: a.sha256.clone(),
                            }],
                        }],
                    )
                })
                .collect(),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_embedded_catalog_pins_lgpl_builds_for_windows_and_linux() {
        let c = FfmpegCatalog::embedded();
        assert_eq!(c.version, 1);
        assert!(is_tag(&c.tag));
        assert_eq!(c.license, "LGPL-2.1-or-later");
        for p in ["windows-x64", "windows-arm64", "linux-x64", "linux-arm64"] {
            let a = c.asset(p).unwrap_or_else(|| panic!("{p} is pinned"));
            assert!(a.name.contains("lgpl-shared"), "{}", a.name);
            assert!(a.url.starts_with(URL_PREFIX));
        }
        assert!(c.asset("macos-arm64").is_none(), "no LGPL macOS build is pinned yet");
        let rc = c.as_runtime_catalog();
        assert_eq!(rc.tag, c.tag);
        assert_eq!(rc.platforms["linux-x64"][0].assets[0].sha256, c.platforms["linux-x64"].sha256);
        assert!(!current_platform().is_empty());
    }

    #[test]
    fn invalid_entries_are_dropped() {
        let good = FfmpegCatalog::embedded();
        let mut v = serde_json::to_value(&good).unwrap();
        v["platforms"]["windows-x64"]["sha256"] = "XYZ".into();
        v["platforms"]["linux-x64"]["url"] = "https://example.org/ffmpeg.tar.xz".into();
        v["platforms"]["linux-arm64"]["name"] = "ffmpeg-gpl.tar.xz".into();
        let c = FfmpegCatalog::parse(&v.to_string()).unwrap();
        assert_eq!(c.platforms.keys().collect::<Vec<_>>(), ["windows-arm64"]);
        v["version"] = 2.into();
        assert!(FfmpegCatalog::parse(&v.to_string()).unwrap_err().contains("version 2"));
        v["version"] = 1.into();
        v["tag"] = "../x".into();
        assert!(FfmpegCatalog::parse(&v.to_string()).is_err());
        assert!(FfmpegCatalog::parse("{").is_err());
        assert!(is_archive_name("a-b_1.tar.xz") && !is_archive_name("a.exe") && !is_archive_name("../a.zip"));
    }
}
